// saveRateSnapshots persists every room type + rate plan combination from a
// successful "rates search" response into the local rate_snapshots table, so
// "analytics price-drift" has real history to report on. Best-effort: a
// persistence failure prints a warning and does not fail the search itself --
// the user asked for rates, not for a database write, and got them either way.
//
// This lives on rates_search.go (a "DO NOT EDIT" generated file) rather than
// as a separate command because "analytics price-drift" can only ever be
// fed by whatever the widget's real avail response looked like at search
// time; a standalone "snapshot" command would just have to re-run the exact
// same search and duplicate this parsing.
func saveRateSnapshots(cmd *cobra.Command, data []byte, hotelID, checkIn, checkOut, currency string) {
	var stays []types.AvailRoomStay
	if err := json.Unmarshal(data, &stays); err != nil {
		fmt.Fprintf(cmd.ErrOrStderr(), "warning: --save could not parse search results: %v\n", err)
		return
	}

	db, err := openStore(cmd.Context())
	if err != nil || db == nil {
		fmt.Fprintf(cmd.ErrOrStderr(), "warning: --save could not open the local store: %v\n", err)
		return
	}
	defer db.Close()

	capturedAt := time.Now().UTC().Format(time.RFC3339)
	saved := 0
	for _, stay := range stays {
		ratePlanNames := make(map[string]string, len(stay.RatePlans))
		for _, rp := range stay.RatePlans {
			ratePlanNames[rp.RatePlanCode] = rp.RatePlanName
		}
		for _, rt := range stay.RoomTypes {
			for _, rate := range rt.AverageRates {
				snap := &store.RateSnapshot{
					HotelID:      hotelID,
					CheckIn:      checkIn,
					CheckOut:     checkOut,
					RoomTypeCode: rt.RoomTypeCode,
					RoomTypeName: rt.RoomTypeName,
					RatePlanCode: rate.RatePlanCode,
					RatePlanName: ratePlanNames[rate.RatePlanCode],
					NightlyRate:  rate.Rate,
					Currency:     currency,
					CapturedAt:   capturedAt,
				}
				if err := db.InsertRateSnapshot(cmd.Context(), snap); err != nil {
					fmt.Fprintf(cmd.ErrOrStderr(), "warning: --save failed to persist a rate snapshot: %v\n", err)
					continue
				}
				saved++
			}
		}
	}
	if saved > 0 {
		fmt.Fprintf(cmd.ErrOrStderr(), "saved %d rate snapshot(s) for hotel %s\n", saved, hotelID)
	}
}
